DIRECTORY_TEMPLATE = '''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#f5f2eb"><meta name="description" content="Browse school website profiles managed by Markandey Pustak Mandir."><title>School directory · Markandey Pustak Mandir</title><link rel="stylesheet" href="../assets/multi-school.css"><script defer src="../assets/multi-school.js"></script></head><body data-page-type="directory" data-data-url="../school-data/schools.json" data-root-prefix="../"><div class="topline"><div class="wrap"><span data-en="MARKANDEY PUSTAK MANDIR · SCHOOL WEBSITES" data-hi="मार्कण्डेय पुस्तक मंदिर · विद्यालय वेबसाइट">MARKANDEY PUSTAK MANDIR · SCHOOL WEBSITES</span><button class="language" data-language-toggle type="button">हिन्दी</button></div></div><header class="header"><div class="wrap nav"><a class="brand" href="../"><span class="seal">MP</span><span><strong>Markandey Pandey Pustak Mandir</strong><small data-en="School website directory · Gorakhpur" data-hi="विद्यालय वेबसाइट सूची · गोरखपुर">School website directory · Gorakhpur</small></span></a><button class="menu" type="button" aria-label="Open menu">☰</button><nav class="navlinks"><a href="../" data-en="Main website" data-hi="मुख्य वेबसाइट">Main website</a><a class="nav-cta" href="#directory" data-en="Browse schools ↓" data-hi="विद्यालय देखें ↓">Browse schools ↓</a></nav></div></header><main class="wrap"><section class="directory-hero"><p class="eyebrow" data-en="ONE SHARED DESIGN · EVERY SCHOOL’S STORY" data-hi="एक साझा डिज़ाइन · हर विद्यालय की अपनी कहानी">ONE SHARED DESIGN · EVERY SCHOOL’S STORY</p><h1 data-en="Find your school." data-hi="अपना विद्यालय खोजें।">Find your school.</h1><p data-en="Each school has its own name, photos, class lists, uniform guide and contact details, presented in one familiar layout." data-hi="हर विद्यालय का अपना नाम, तस्वीरें, कक्षा सूची, वेशभूषा मार्गदर्शिका और संपर्क जानकारी है, एक परिचित डिज़ाइन में।">Each school has its own name, photos, class lists, uniform guide and contact details, presented in one familiar layout.</p><div class="directory-tools"><input type="search" data-school-search placeholder="Search by school or area…" aria-label="Search schools"></div><p data-directory-count></p><div class="school-grid" data-school-grid></div></section></main><footer class="footer"><div class="wrap footer-inner"><strong>Markandey Pandey Pustak Mandir</strong><small data-en="School profiles are sample concepts. Confirm details with each school." data-hi="विद्यालय परिचय नमूना हैं। हर विद्यालय से विवरण की पुष्टि करें।">School profiles are sample concepts. Confirm details with each school.</small><a href="../" data-en="Main website ↗" data-hi="मुख्य वेबसाइट ↗">Main website ↗</a></div></footer></body></html>'''


def esc(value: object) -> str:
    return html.escape(str(value or ""), quote=True)

def valid_slug(value: str) -> bool:
    return bool(re.fullmatch(r"[a-z0-9]+(?:-[a-z0-9]+)*", value))

def main() -> None:
    payload = json.loads(DATA.read_text(encoding="utf-8"))
    schools = payload.get("schools", [])
    active = [school for school in schools if school.get("active", True)]
    seen: set[str] = set()
    for school in active:
        slug = school.get("slug", "")
        if not valid_slug(slug) or slug in seen:
            raise SystemExit(f"Invalid or repeated school link: {slug!r}")
        seen.add(slug)
        for field in ("name", "locality", "motto", "intro"):
            if not school.get(field):
                raise SystemExit(f"{slug}: please fill in {field}")
    out = ROOT / "s"
    previous_file = out / ".generated-slugs.json"
    previous = json.loads(previous_file.read_text()) if previous_file.exists() else []
    for stale in set(previous) - seen:
        old_dir = out / stale
        old_page = old_dir / "index.html"
        if old_page.exists(): old_page.unlink()
        if old_dir.exists() and not any(old_dir.iterdir()): old_dir.rmdir()
    for school in active:
        slug = school["slug"]
        values = {
            "__SOFT__": esc(school.get("soft", "#e8eee5")), "__DESCRIPTION__": esc(school.get("intro", school["name"])),
            "__NAME__": esc(school["name"]), "__SLUG__": esc(slug), "__ACCENT__": esc(school.get("accent", "#496b55")),
            "__LOGO__": esc(school.get("logo", "SCH")), "__LOCALITY__": esc(school["locality"]),
            "__MOTTO__": esc(school["motto"]), "__INTRO__": esc(school["intro"])
        }
        page = SCHOOL_TEMPLATE
        for key, value in values.items(): page = page.replace(key, value)
        target = out / slug / "index.html"
        target.parent.mkdir(parents=True, exist_ok=True)
        target.write_text(page, encoding="utf-8")
    previous_file.write_text(json.dumps(sorted(seen), indent=2) + "\n", encoding="utf-8")
    directory = ROOT / "schools" / "index.html"
    directory.parent.mkdir(parents=True, exist_ok=True)
    directory.write_text(DIRECTORY_TEMPLATE, encoding="utf-8")
    print(f"Generated {len(active)} school profiles in /s/<slug>/ and the /schools/ directory.")

if __name__ == "__main__": main()
